"""Training-only response supervision on physically coupled counterfactual pairs."""

import math

import torch


@torch.no_grad()
def paired_sensor_increment_units(clean_a, clean_b, shot, *, floor_DN16=16):
    """Nominal std of the coupled sensor difference, with a fixed DN16 floor.

    Common Poisson counts and Gaussian read noise cancel before ADC; the
    remaining variance is effective_shot*abs(clean_a-clean_b). These are
    sensor-increment training units, not restored RGB covariance/confidence.
    The inherited positive-shot floor is 1e-12. Targets/units never enter forward.
    """
    if clean_a.ndim != 4 or clean_a.shape != clean_b.shape or min(clean_a.shape) < 1:
        raise ValueError("Expected matching nonempty N x C x H x W sensor tensors")
    if not all(v.is_floating_point() and torch.isfinite(v).all() for v in (clean_a, clean_b)):
        raise ValueError("Sensor values must be finite floating-point tensors")
    if clean_a.device != clean_b.device or (clean_a < 0).any() or (clean_b < 0).any():
        raise ValueError("Sensor values must be nonnegative on the same device")
    if not math.isfinite(floor_DN16) or floor_DN16 <= 0:
        raise ValueError("Noise-unit floor must be positive and finite")
    dtype = torch.float64 if clean_a.dtype == torch.float64 else torch.float32
    a, b = clean_a.to(dtype), clean_b.to(dtype)
    coefficient = torch.as_tensor(shot, device=a.device, dtype=dtype)
    if not torch.isfinite(coefficient).all() or (coefficient < 0).any():
        raise ValueError("Shot coefficient must be finite and nonnegative")
    try:
        coefficient = torch.broadcast_to(coefficient, a.shape)
    except RuntimeError as error:
        raise ValueError("Shot coefficient must broadcast within the sensor shape") from error
    coefficient = torch.where(coefficient > 0, coefficient.clamp_min(1e-12), coefficient)
    variance = coefficient * (a - b).abs()
    if variance.shape != a.shape:
        raise ValueError("Shot coefficient must broadcast within the sensor shape")
    return variance.mean((1, 2, 3), keepdim=True).sqrt().clamp_min(floor_DN16 / 65535)


def paired_response_loss(output, target, units, pairs, *, epsilon=0.003):
    """Stable Charbonnier of restored-minus-target pair differences.

    Each model forward sees one noisy image and its supplied parent. This loss
    operates afterwards on disjoint aligned pairs, including exactly unchanged
    target regions. It is blind to RGB errors shared by both members, so ordinary
    RGB/local/DC losses remain necessary. No inference gate or flat guarantee.
    """
    if output.ndim != 4 or output.shape[1] != 3 or min(output.shape) < 1:
        raise ValueError("Expected nonempty N x 3 x H x W output")
    if target.shape != output.shape or not all(v.is_floating_point() for v in (output, target)):
        raise ValueError("Output and target must be matching floating-point RGB")
    if not math.isfinite(epsilon) or epsilon <= 0:
        raise ValueError("Charbonnier epsilon must be positive and finite")
    indices = torch.as_tensor(pairs, device=output.device)
    if (
        indices.dtype != torch.int64
        or indices.ndim != 2
        or indices.shape[1] != 2
        or len(indices) < 1
    ):
        raise ValueError("Expected nonempty P x 2 int64 pair indices")
    if (
        indices.min() < 0
        or indices.max() >= len(output)
        or indices.unique().numel() != indices.numel()
    ):
        raise ValueError("Pair members must be distinct and in range")
    if units.shape != (len(indices), 1, 1, 1) or not units.is_floating_point():
        raise ValueError("Expected one floating-point unit per pair")
    if not torch.isfinite(units).all() or (units <= 0).any():
        raise ValueError("Pair units must be positive and finite")
    dtype = torch.float64 if output.dtype == torch.float64 else torch.float32
    with torch.autocast(output.device.type, enabled=False):
        value, clean = output.to(dtype), target.detach().to(device=output.device, dtype=dtype)
        scale = units.detach().to(device=output.device, dtype=dtype)
        first, second = indices.unbind(1)
        residual = ((value[first] - value[second]) - (clean[first] - clean[second])) / scale
        power = residual.square()
        return (power / ((power + epsilon**2).sqrt() + epsilon)).mean()

"""Training-only absolute RGB supervision inside locally flat clean targets."""

import math

import torch
from torch.nn import functional as F


def _rgb(value):
    return (
        value.ndim == 4
        and value.shape[1] == 3
        and min(value.shape) > 0
        and value.is_floating_point()
    )


@torch.no_grad()
def flat_target_mask(target, *, window=17, tolerance_DN16=1):
    """Select pixels whose truncated neighborhood range is small in every RGB channel.

    Channel offsets are preserved: a spatially constant colored field qualifies.
    The clean target supplies a training weight, never an inference input. A
    selected weak gradient is still supervised against its actual target rather
    than replaced with a constant. Separable maxima/minima are exact, including
    image borders; no averaging or variance cancellation defines eligibility.
    """
    if not _rgb(target) or not torch.isfinite(target).all():
        raise ValueError("Expected finite nonempty N x 3 x H x W clean targets")
    if not isinstance(window, int) or window < 1 or window % 2 != 1:
        raise ValueError("Flat-target window must be a positive odd integer")
    if not math.isfinite(tolerance_DN16) or tolerance_DN16 < 0:
        raise ValueError("Flat-target tolerance must be finite and nonnegative")
    value = target.detach().to(torch.float64 if target.dtype == torch.float64 else torch.float32)
    radius = window // 2

    def maximum(x):
        x = F.max_pool2d(x, (1, window), stride=1, padding=(0, radius))
        return F.max_pool2d(x, (window, 1), stride=1, padding=(radius, 0))

    ranges = maximum(value) + maximum(-value)
    return ranges.amax(1, keepdim=True) <= tolerance_DN16 / 65535


def flat_target_anchor_loss(output, target, mask, *, unit_DN16=16):
    """Mean pseudo-Huber RGB target error at fixed DN16 units under a clean mask.

    rho(z)=sqrt(1+z^2)-1, evaluated without small-error cancellation. The mean
    includes all image elements, so mask coverage controls the term's weight;
    an almost empty mask does not receive the weight of a completely flat image.
    Targets detach. This complements pair differences by penalizing common RGB
    errors in eligible regions, without penalizing corrections toward the target.
    """
    if not _rgb(output) or not _rgb(target) or output.shape != target.shape:
        raise ValueError("Expected matching nonempty floating-point RGB tensors")
    if output.device != target.device or mask.device != output.device:
        raise ValueError("Output, target and mask must share a device")
    if mask.dtype != torch.bool or mask.shape != (len(output), 1, *output.shape[-2:]):
        raise ValueError("Expected an N x 1 x H x W boolean eligibility mask")
    if not math.isfinite(unit_DN16) or unit_DN16 <= 0:
        raise ValueError("Anchor units must be positive and finite")
    dtype = torch.float64 if output.dtype == torch.float64 else torch.float32
    with torch.autocast(output.device.type, enabled=False):
        error = (output.to(dtype) - target.detach().to(dtype)) / (unit_DN16 / 65535)
        power = error.square()
        return (power / ((power + 1).sqrt() + 1) * mask).mean()

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_bounded_support_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = Path('/home/dllu/proj/demosaic/.cache/quality-20261103') / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 3288 and retained == 1398 and real == 30 and len(result["rows"]) == 4686
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 4686,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())
